export function actionId(serviceId,name){return `act_${serviceId}_${String(name).toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'').slice(0,48)}`}
export function fieldsFor(action){const preset=PRESETS[action[4]]||PRESETS.basic;return preset.map((x,i)=>({label:x[0],type:x[1],required:x[2],profileKey:x[3]||'',options:x[4]||[],order:(i+1)*10}))}
